export const lessons: Lesson[] = [
  // ========== HONOR (Age 8) ==========
  
  // MATH - Honor
  { id: 'honor-math-1', title: 'Addition & Subtraction to 100', subject: 'math', grade: 'honor', description: 'Practice adding and subtracting numbers up to 100', content: '# Addition & Subtraction to 100\n\n## Let\'s Practice!\n\n**Addition**\n\n45 + 32 = ?\n\nStep 1: Add the ones: 5 + 2 = 7\nStep 2: Add the tens: 4 + 3 = 7\nAnswer: **77**\n\n**Try these:**\n- 23 + 45 = ?\n- 67 + 18 = ?\n- 89 - 34 = ?\n- 72 - 29 = ?\n\n**Word Problem**\n\nHonor had 45 crayons. He bought 28 more at the store. How many crayons does he have now?\nAnswer: 45 + 28 = **73 crayons**', difficulty: 'easy', duration: '20 min' },
  { id: 'honor-math-2', title: 'Multiplication Basics (1-5)', subject: 'math', grade: 'honor', description: 'Learn your multiplication tables for numbers 1-5', content: '# Multiplication Basics\n\n## What is Multiplication?\n\nMultiplication is fast adding!\n\n3 x 4 means 3 groups of 4\n3 + 4 = 7 (not correct)\n3 + 3 + 3 + 3 = 12 (correct)\n\n**The 2 Times Table**\n- 2 x 1 = 2\n- 2 x 2 = 4\n- 2 x 3 = 6\n- 2 x 4 = 8\n- 2 x 5 = 10\n\n**The 3 Times Table**\n- 3 x 1 = 3\n- 3 x 2 = 6\n- 3 x 3 = 9\n- 3 x 4 = 12\n- 3 x 5 = 15\n\n**Practice:**\n- 4 x 3 = ?\n- 5 x 2 = ?\n- 3 x 7 = ?', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-math-3', title: 'Fractions Made Easy', subject: 'math', grade: 'honor', description: 'Learn what fractions are using pizza and shapes', content: '# Fractions Made Easy\n\n## What is a Fraction?\n\nA fraction is a part of a whole.\n\n**Pizza Example**\n\nA pizza has 8 slices. You eat 2 slices.\n\nYou ate: 2/8 = 1/4 of the pizza\n\n**Parts of a Fraction**\n\n2/4\n- Top number (2) = how many parts we have\n- Bottom number (4) = total parts\n\n**Try These:**\n\n- A cake has 6 slices. You eat 3. What fraction did you eat?\n- A rectangle has 4 parts. 1 is shaded. What fraction is shaded?\n\n**Practice:**\n- 1/2 of 10 = ?\n- 1/4 of 8 = ?\n- 2/3 of 6 = ?', difficulty: 'medium', duration: '25 min' },
  { id: 'honor-math-4', title: 'Geometry: Shapes', subject: 'math', grade: 'honor', description: 'Learn about 2D shapes and their sides', content: '# Geometry: Shapes\n\n## 2D Shapes\n\n**Triangle** - 3 sides, 3 corners\n**Square** - 4 equal sides, 4 corners\n**Rectangle** - 4 sides, 4 corners (opposite sides equal)\n**Pentagon** - 5 sides\n**Hexagon** - 6 sides\n**Circle** - 0 sides, 1 curved edge\n\n## Count the Sides\n\n- How many sides does a hexagon have? **6**\n- How many sides does a triangle have? **3**\n- A shape with 4 equal sides is a **square**\n\n## Activity\n\nLook around your room and find:\n- 2 triangles\n- 2 rectangles\n- 1 circle\n\n**Challenge:**\nDraw a shape with 7 sides. What is it called? (Heptagon!)', difficulty: 'easy', duration: '20 min' },
  { id: 'honor-math-5', title: 'Place Value', subject: 'math', grade: 'honor', description: 'Learn ones, tens, and hundreds', content: '# Place Value\n\n## What is Place Value?\n\nEach spot in a number has a different value!\n\n**The Number 347**\n\n- 3 is in the **hundreds** place = 300\n- 4 is in the **tens** place = 40\n- 7 is in the **ones** place = 7\n\n300 + 40 + 7 = 347\n\n## Practice\n\n**What is 256?**\n- 2 hundreds = 200\n- 5 tens = 50\n- 6 ones = 6\n\n**Break these numbers:**\n- 482 = ?\n- 915 = ?\n- 367 = ?\n\n## Bigger Numbers\n\n**1,234** = 1 thousand + 2 hundreds + 3 tens + 4 ones\n\n**Practice:**\n- What is the value of 5 in 5,621?\n- What is the value of 8 in 3,894?', difficulty: 'medium', duration: '25 min' },
  { id: 'honor-math-6', title: 'Money Math', subject: 'math', grade: 'honor', description: 'Count coins and make change', content: '# Money Math\n\n## Coins We Use\n\n**Penny** = 1 cent (1¢)\n**Nickel** = 5 cents (5¢)\n**Dime** = 10 cents (10¢)\n**Quarter** = 25 cents (25¢)\n\n## Counting Coins\n\nHow much is this?\n3 quarters + 2 dimes + 1 nickel + 4 pennies\n\n75¢ + 20¢ + 5¢ + 4¢ = **$1.04**\n\n## Practice\n\n**How much?**\n- 2 quarters + 3 dimes = ?\n- 1 quarter + 5 nickels + 10 pennies = ?\n- 4 dimes + 7 pennies = ?\n\n## Making Change\n\nYou have $1.00 and buy something for 65¢.\n\nHow much change do you get?\n\n$1.00 - 65¢ = **35¢**\n\n(25¢ + 10¢ = 1 quarter + 1 dime)', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-math-7', title: 'Telling Time', subject: 'math', grade: 'honor', description: 'Learn to read clocks and understand time', content: '# Telling Time\n\n## Parts of a Clock\n\n- **Hour hand** (short) = tells what hour\n- **Minute hand** (long) = tells the minutes\n\n## Reading Clocks\n\nWhen minute hand is on 12, it\'s :00 (o\'clock)\n\nWhen minute hand is on 6, it\'s :30 (half past)\n\n**Examples:**\n- Short hand on 3, long hand on 12 = **3:00**\n- Short hand past 5, long hand on 6 = **5:30**\n- Short hand on 7, long hand on 12 = **7:00**\n\n## AM vs PM\n\n**AM** = Morning (12:00 midnight to 11:59 morning)\n**PM** = Afternoon/Night (12:00 noon to 11:59 night)\n\n## Practice\n\nWhat time is it?\n- 3:00 - three o\'clock\n- 6:30 - half past six\n- 9:15 - quarter past nine\n- 11:45 - quarter to twelve', difficulty: 'easy', duration: '20 min' },

  // READING - Honor
  { id: 'honor-reading-1', title: 'Story Elements', subject: 'reading', grade: 'honor', description: 'Learn about characters, setting, and plot', content: '# Story Elements\n\n## Every Story Has Parts\n\n**1. Characters**\nWho is in the story?\n(People, animals, or creatures)\n\n**2. Setting**\nWhere and when does the story happen?\n\n**3. Plot (What Happens)**\n- Beginning: How does the story start?\n- Middle: What is the problem?\n- End: How is the problem solved?\n\n## Let\'s Practice\n\nRead this short story:\n\n"Lily found a lost puppy in the park. She took him home and named him Biscuit. Every day after, Lily and Biscuit became best friends."\n\n**Characters:** Lily, Biscuit (the puppy)\n**Setting:** A park, then Lily\'s home\n**Plot:** Beginning - finding puppy | Middle - naming him | End - becoming friends\n\n## Your Turn\n\nThink of your favorite book:\n- Who are the characters?\n- Where does the story happen?\n- What is the problem and how is it solved?', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-reading-2', title: 'Main Idea & Details', subject: 'reading', grade: 'honor', description: 'Find the main idea and supporting details', content: '# Main Idea & Details\n\n## What is the Main Idea?\n\nThe main idea is what the whole text is mostly about.\n\n**Example**\n\nParagraph about dogs: playing fetch, eating kibble, going on walks, sleeping in beds\n\n**Main Idea:** Dogs make great pets\n\n## Supporting Details\n\nDetails are small facts that help explain the main idea.\n\n**Main Idea:** Dogs make great pets\n\n**Details:**\n- They love to play\n- They are loyal\n- They keep you company\n\n## Practice\n\nWhat is the main idea?\n\n"Sunflowers grow tall. They have big yellow flowers. Birds eat their seeds. Farmers grow them for seeds and oil."\n\n**Main Idea:** Sunflowers are tall plants with yellow flowers\n\n**Your Turn:**\nWrite 2 details about your favorite animal.', difficulty: 'medium', duration: '25 min' },
  { id: 'honor-reading-3', title: 'Nouns: People, Places, Things', subject: 'reading', grade: 'honor', description: 'Learn about different types of nouns', content: '# Nouns: People, Places, Things\n\n## What is a Noun?\n\nA noun is a word that names:\n- A **person** (people you can name)\n- A **place** (locations)\n- A **thing** (objects)\n\n## Examples\n\n**People:**\nMom, teacher, doctor, friend, policeman\n\n**Places:**\nschool, park, library, ocean, city\n\n**Things:**\nbook, ball, car, apple, music\n\n## Practice\n\nIs it a noun? YES or NO?\n- cat - YES (thing)\n- run - NO (that\'s a verb!)\n- happy - NO (that\'s an adjective!)\n- house - YES (place/thing)\n- teacher - YES (person)\n\n## Sort These Nouns\n\nWrite each word in the right column:\n\n| Person | Place | Thing |\n|--------|-------|-------|\n| | | |\n| | | |\n| | | |\n\ndog, grandma, beach, ball, police officer, garden', difficulty: 'easy', duration: '20 min' },
  { id: 'honor-reading-4', title: 'Verbs: Action Words', subject: 'reading', grade: 'honor', description: 'Learn about verbs and what they do', content: '# Verbs: Action Words\n\n## What is a Verb?\n\nA verb is a word that shows:\n- An **action** (what someone does)\n- A **state of being** (exists as)\n\n## Action Verbs Examples\n\n**Running:** jump, skip, run, walk\n**Talking:** say, speak, shout, whisper\n**Creating:** build, draw, paint, write\n\n## Practice\n\n**Which word is the verb?**\n\n1. The dog **barks** loudly.\n   - Verb: barks\n\n2. She **reads** her book.\n   - Verb: reads\n\n3. They **play** soccer at the park.\n   - Verb: play\n\n**Find the verbs:**\n- Mom cooks dinner. -\n- The bird sings beautifully. -\n- We swim in the pool. -\n\n## Verb or Not?\n\nCircle the verbs:\n- jump (yes)\n- happy (no)\n- build (yes)\n- green (no)\n- think (yes)', difficulty: 'easy', duration: '20 min' },
  { id: 'honor-reading-5', title: 'Rhymes and Patterns', subject: 'reading', grade: 'honor', description: 'Learn about rhyming words and sound patterns', content: '# Rhymes and Patterns\n\n## What is Rhyme?\n\nWords that sound alike at the end!\n\n**Examples:**\n- cat, hat, bat, rat\n- book, look, cook\n- night, light, bright, fight\n\n## Practice Rhyme\n\nWhat rhymes with...?\n\n- "ball" - wall, tall, call\n- "day" - say, play, stay\n- "tree" - see, be, key\n\n## Rhyming Patterns\n\n**-at family:** cat, hat, rat, mat, bat, sat, flat\n**-op family:** hop, mop, top, pop, stop\n**-ight family:** night, light, right, fight, sight\n\n## Create a Rhyme\n\nFinish each sentence with a rhyming word:\n\n1. The cat sat on the ___ (mat)\n2. I see a bee in a ___-__ (bush)\n3. Run fast like a ___-___ (cheetah)\n\n## Song Practice\n\nSing or read this rhyme:\n\n"Humpty Dumpty sat on a wall,\nHumpty Dumpty had a great fall,\nAll the king\'s horses and all the king\'s men,\nCouldn\'t put Humpty together again."', difficulty: 'easy', duration: '20 min' },

  // SCIENCE - Honor
  { id: 'honor-science-1', title: 'The Solar System', subject: 'science', grade: 'honor', description: 'Learn about the sun and planets', content: '# The Solar System\n\n## Our Solar System\n\nThe Solar System is our neighborhood in space!\n\n**The Sun**\n- A giant ball of hot gas\n- Gives us light and heat\n- All planets orbit (travel around) the Sun\n\n## The 8 Planets\n\n**Inner Planets (rocky):**\n1. Mercury - smallest, closest to Sun\n2. Venus - hottest planet\n3. Earth - our home! Has water\n4. Mars - the red planet\n\n**Outer Planets (gassy):**\n5. Jupiter - biggest planet\n6. Saturn - has beautiful rings\n7. Uranus - tilts sideways\n8. Neptune - farthest from Sun\n\n## Fun Facts\n\n- Earth takes 365 days to orbit the Sun (that is 1 year!)\n- The Moon orbits Earth\n- Stars are far away suns\n\n## Activity\n\nDraw the solar system in order!\nHint: Start with the Sun, then Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune', difficulty: 'medium', duration: '30 min' },
  { id: 'honor-science-2', title: 'Plants: How They Grow', subject: 'science', grade: 'honor', description: 'Learn what plants need to survive', content: '# Plants: How They Grow\n\n## What Plants Need\n\nAll plants need these 4 things:\n\n1. **Sunlight** - Gives energy\n2. **Water** - Helps it grow\n3. **Air** - To breathe\n4. **Soil** - Roots hold the plant up, gives food\n\n## Parts of a Plant\n\n- **Roots** - Grow underground, soak up water\n- **Stem** - Holds the plant up\n- **Leaves** - Make food using sunlight\n- **Flower** - Makes seeds for new plants\n\n## How a Plant Grows\n\n**Step 1:** Plant a seed in soil\n**Step 2:** Water it\n**Step 3:** Place in sunlight\n**Step 4:** Wait! Roots grow first\n**Step 5:** A small plant appears!\n**Step 6:** More leaves, maybe flowers!\n\n## Try at Home\n\nPlant a bean seed in a cup! Watch it grow and draw what you see each day.\n\n**Questions:**\n- What happens if a plant has no water?\n- What happens if there is no sunlight?', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-science-3', title: 'Animals and Their Needs', subject: 'science', grade: 'honor', description: 'Learn what animals need to survive', content: '# Animals and Their Needs\n\n## What Do Animals Need?\n\nAll animals need:\n\n1. **Food** - To have energy and grow\n2. **Water** - To survive\n3. **Shelter** - A safe place to live\n4. **Air** - To breathe\n\n## Types of Animals\n\n**Mammals** - Have fur/hair, drink milk from mom (dog, cat, human)\n**Birds** - Have feathers, most can fly (eagle, robin, owl)\n**Fish** - Live in water, have fins (goldfish, shark, clownfish)\n**Reptiles** - Cold-blooded, have scales (lizard, turtle, snake)\n**Insects** - Have 6 legs (butterfly, ant, bee)\n\n## Where Do Animals Live?\n\n- **Forest** - deer, squirrels, birds\n- **Ocean** - fish, whales, dolphins\n- **Desert** - camels, lizards, snakes\n- **Arctic** - polar bears, penguins, seals\n\n## Think About It\n\nWhy do you think polar bears have thick fur?\nWhy do fish have gills?\nWhy do birds build nests?', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-science-4', title: 'Weather and Seasons', subject: 'science', grade: 'honor', description: 'Learn about different weather and why we have seasons', content: '# Weather and Seasons\n\n## What is Weather?\n\nWeather is what the sky and air are like outside!\n\n**Sunny** - Clear sky, bright sun\n**Cloudy** - Lots of clouds in the sky\n**Rainy** - Water falling from clouds\n**Windy** - Lots of moving air\n**Snowy** - Very cold, frozen precipitation\n**Stormy** - Thunder, lightning, heavy rain\n\n## The Four Seasons\n\n**Spring** - Gets warmer, flowers bloom, baby animals born\n**Summer** - Hot, sunny, long days\n**Fall/Autumn** - Cooler, leaves change color and fall\n**Winter** - Cold, shorter days, sometimes snow\n\n## Why Do We Have Seasons?\n\nEarth tilts as it goes around the Sun!\n\nWhen your part of Earth tilts TOWARD the Sun = **Summer**\nWhen your part of Earth tilts AWAY from the Sun = **Winter**\n\n## Weather Safety\n\n- **Lightning** - Go inside!\n- **Tornado** - Go to a safe room!\n- **Hot day** - Drink water, wear sunscreen!', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-science-5', title: 'The Human Body', subject: 'science', grade: 'honor', description: 'Learn about major body parts and systems', content: '# The Human Body\n\n## Body Parts We Know\n\n- Head, neck, shoulders, arms, hands\n- Chest, back, stomach\n- Legs, feet, toes\n\n## Inside Our Bodies\n\n**Brain** - Controls everything you do! Thinking, moving, feeling\n**Heart** - Pumps blood through your body (lub-dub, lub-dub!)\n**Lungs** - Help you breathe in air\n**Stomach** - Breaks down food\n**Bones** - Give your body shape and protect organs\n\n## Amazing Body Facts\n\n- You have more than 200 bones!\n- Your heart beats about 100,000 times a day!\n- You breathe about 20,000 times a day!\n- Your brain weighs about 3 pounds\n\n## Take Care of Your Body\n\n- Eat healthy foods\n- Drink lots of water\n- Exercise and play\n- Get plenty of sleep\n- Wash your hands!', difficulty: 'easy', duration: '25 min' },

  // SOCIAL STUDIES - Honor
  { id: 'honor-ss-1', title: 'Your Community', subject: 'social-studies', grade: 'honor', description: 'Learn about places in your community', content: '# Your Community\n\n## What is a Community?\n\nA community is a place where people live, work, and help each other.\n\n## Places in Our Community\n\n**School** - Where we learn\n**Library** - Where we borrow books\n**Hospital** - Where we get help when sick\n**Fire Station** - Firefighters help us\n**Police Station** - Police keep us safe\n**Park** - Place to play and have fun\n**Store** - Where we buy food and things\n**Church/Temple** - Place to worship\n\n## Community Helpers\n\nThese people help our community:\n\n- Teachers\n- Doctors & Nurses\n- Firefighters\n- Police Officers\n- Librarians\n- Bus Drivers\n- Farmers\n\n## Think About It\n\n- Who are the community helpers in YOUR neighborhood?\n- What places do you visit most?\n- How do these people help you?\n\n## Activity\n\nDraw a map of your neighborhood. Include:\n- Your home\n- Your school\n- 3 other places\n- A community helper', difficulty: 'easy', duration: '20 min' },
  { id: 'honor-ss-2', title: 'Maps and Directions', subject: 'social-studies', grade: 'honor', description: 'Learn north, south, east, west and how to read maps', content: '# Maps and Directions\n\n## Cardinal Directions\n\n**N**orth - Up on the map\n**S**outh - Down on the map\n**E**ast - Right on the map\n**W**est - Left on the map\n\n**Tip:** Never Eat Soggy Worms (North, East, South, West)\n\n## Using a Map\n\n**Compass Rose** - Shows which way is north\n\n**Map Key/Legend** - Tells you what symbols mean\n\n- ⭐ = Star (maybe a park)\n- 🏠 = House\n- 🏫 = School\n- ⛪ = Church\n\n## Practice Directions\n\nIf North is UP:\n- South is... DOWN\n- East is... RIGHT\n- West is... LEFT\n\n**If you start at HOME and go North, then East - where are you?**\n\n## Activity\n\nDraw a simple map of your room!\n- Where is your bed?\n- Where is your door?\n- Use N at the top of your map', difficulty: 'easy', duration: '20 min' },
  { id: 'honor-ss-3', title: 'American Holidays', subject: 'social-studies', grade: 'honor', description: 'Learn about major US holidays', content: '# American Holidays\n\n## January\n\n**New Year\'s Day** - January 1\nCelebrates the start of a new year!\n\n## February\n\n**Presidents\' Day** - Third Monday\nHonors past US presidents\n\n## March/April\n\n**Easter** - Varies\nChristian celebration of new life\n\n## May\n\n**Memorial Day** - Last Monday\nHonors people who died in military service\n\n## July\n\n**Independence Day** - July 4th\nCelebrates America\'s birthday! Fireworks and flags!\n\n## September\n\n**Labor Day** - First Monday\nHonors workers\n\n## October\n\n**Halloween** - October 31st\nCostumes, candy, spooky fun!\n\n## November\n\n**Thanksgiving** - Fourth Thursday\nFamily dinner with turkey and pie!\n\n## December\n\n**Christmas** - December 25th\nPresents, trees, celebrations\n\n**Hanukkah** - Varies\nJewish Festival of Lights\n\n**Kwanzaa** - December 26th\nCelebrates African American culture', difficulty: 'easy', duration: '20 min' },

  // ART - Honor
  { id: 'honor-art-1', title: 'Drawing Basics', subject: 'art', grade: 'honor', description: 'Learn to draw shapes and build from them', content: '# Drawing Basics\n\n## Everything is Shapes!\n\nYou can draw ANYTHING using basic shapes!\n\n**Basic Shapes:**\n- Circle\n- Oval\n- Square\n- Rectangle\n- Triangle\n\n## Drawing Animals with Shapes\n\n**Cat:**\n1. Large oval for body\n2. Circle for head\n3. Triangles for ears\n4. Thin rectangles for legs\n5. Long curve for tail\n\n**Dog:**\n1. Oval for body\n2. Circle for head\n3. Floppy oval ears\n4. Rectangle tongue\n5. Curved tail\n\n## Practice Challenges\n\n**Challenge 1:** Draw 5 different animals using only circles, ovals, triangles, and rectangles.\n\n**Challenge 2:** Draw your house using shapes.\n\n**Challenge 3:** Draw your family as cartoon characters!\n\n## Tips\n\n- Start light, then go darker\n- Use smooth lines\n- Step back to check proportions\n- Do not worry about mistakes - they are part of learning!\n\n## Have Fun!\n\nCreate your own imaginary creature using shapes. Give it a name and tell a story about it!', difficulty: 'easy', duration: '30 min' },
  { id: 'honor-art-2', title: 'Famous Artists', subject: 'art', grade: 'honor', description: 'Learn about famous artists and their styles', content: '# Famous Artists\n\n## What is Art?\n\nArt is when people create something beautiful or meaningful using their imagination and skills!\n\n## Famous Artists\n\n**Pablo Picasso** (Spanish, 1881-1973)\n- Known for: Strange faces, cubes, bold colors\n- He painted people with eyes in weird places!\n\n**Claude Monet** (French, 1840-1926)\n- Known for: Water lilies, gardens, nature\n- He painted the same garden many times at different times of day!\n\n**Vincent van Gogh** (Dutch, 1853-1890)\n- Known for: Swirly skies, bright yellows, starry nights\n- He only sold one painting in his whole life!\n\n**Frida Kahlo** (Mexican, 1907-1954)\n- Known for: Self-portraits with flowers, animals, bright colors\n- She painted what she felt, not just what she saw!\n\n## Activity\n\nTry to draw in the style of one of these artists!\n- Picasso face (eyes in weird spots)\n- Monet garden (soft, dreamy colors)\n- Van Gogh swirls (circles and lines)\n\n## Think About It\n\nWhat do YOU want to create?', difficulty: 'easy', duration: '30 min' },
  { id: 'honor-art-3', title: 'Lines and Patterns', subject: 'art', grade: 'honor', description: 'Learn different types of lines and how to use them', content: '# Lines and Patterns\n\n## Types of Lines\n\n- **Straight** - goes straight across\n- **Curved** - bends like a wave\n- **Zigzag** - goes up and down sharply\n- **Dotted** - made of dots\n- **Spiral** - curls around and around\n\n## Using Lines in Art\n\n**Hatching** - Lines close together that go in one direction\n**Cross-hatching** - Lines that cross each other\n**Contour** - Lines that outline shapes\n**Gesture** - Quick, loose lines that show movement\n\n## Patterns\n\nPatterns are lines or shapes that REPEAT!\n\n**Examples:**\n- Stripes: ▓▓▓▓▓▓\n- Polka dots: ● ● ● ●\n- Zigzag: /\n/\n/\n/\n\n## Create a Pattern\n\nMake your own repeating pattern:\n- Colors: red, blue, red, blue...\n- Shapes: circle, square, circle, square...\n- Lines: straight, curved, straight, curved...\n\n## Activity\n\nDraw a scene using ONLY lines!\n- Use different types of lines for different things\n- Make patterns in the sky, grass, clothes, etc.', difficulty: 'easy', duration: '25 min' },

  // MUSIC - Honor
  { id: 'honor-music-1', title: 'Rhythm Basics', subject: 'music', grade: 'honor', description: 'Learn about beats and rhythm patterns', content: '# Rhythm Basics\n\n## What is Rhythm?\n\nRhythm is the pattern of sounds and silences in music.\n\n**Think of it like a heartbeat:**\n\nTick-Tock, Tick-Tock, Tick-Tock\n\n## Beat and Tempo\n\n**Beat** - The steady pulse in music\n**Tempo** - How fast or slow the beat goes\n\n- Fast tempo = Allegro (happy, exciting)\n- Slow tempo = Adagio (calm, sad)\n- Medium tempo = Moderato\n\n## Rhythm Patterns\n\n**Quarter Note** = 1 beat\n- Sounds like: "TAH"\n\n**Half Note** = 2 beats\n- Sounds like: "TAH-AAAH"\n\n**Whole Note** = 4 beats\n- Sounds like: "TAH-AAAH-TAAAH-AAAAAH"\n\n## Clap Along!\n\nPractice these patterns:\n1. Four quarter notes\n2. Two half notes\n3. Quarter, half, quarter\n\n## Make Your Own!\n\nCreate a 4-beat rhythm using quarter notes, half notes, and rests. Have someone else try to clap it back to you!\n\n**R = Rest (silent)**', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-music-2', title: 'Musical Instruments', subject: 'music', grade: 'honor', description: 'Learn about different families of instruments', content: '# Musical Instruments\n\n## Four Instrument Families\n\n**1. Strings** - Sound from vibrating strings\n- Violin, cello, guitar, harp, piano\n- Makes sounds like singing!\n\n**2. Woodwinds** - Sound from vibrating air\n- Flute, clarinet, saxophone, recorder\n- You blow into them!\n\n**3. Brass** - Sound from buzzing lips\n- Trumpet, trombone, french horn, tuba\n- Makes loud, bold sounds!\n\n**4. Percussion** - Sound from hitting/shaking\n- Drums, cymbals, tambourine, maracas\n- Makes rhythm!\n\n## Fun Facts\n\n- The violin family has been around for 500+ years!\n- A piano has 88 keys and 200+ strings inside!\n- The tuba is the biggest brass instrument\n- Drums were used thousands of years ago!\n\n## Activity\n\nCan you identify instruments by their sound?\n\nListen and guess:\n1. High, squeaky, melody - ?\n2. Deep, booming, rhythm - ?\n3. Twangy, strumming - ?\n4. Buzzy, fanfare sounds - ?\n\n## Make Your Own!\n\nCreate an instrument at home:\n- Rice in a container = shaker\n- Rubber bands on a box = guitar\n- Spoons = percussion!', difficulty: 'easy', duration: '25 min' },
  { id: 'honor-music-3', title: 'Singing and Your Voice', subject: 'music', grade: 'honor', description: 'Learn about your voice and how to use it', content: '# Singing and Your Voice\n\n## Your Voice is an Instrument!\n\nYour voice is made of:\n- **Lungs** - Air source\n- **Vocal cords** - Vibrate to make sound (in your throat)\n- **Mouth** - Shapes the sounds into words and notes\n\n## Voice Types\n\n**Soprano** - High female voices\n**Alto** - Lower female voices\n**Tenor** - High male voices\n**Bass** - Lower male voices\n\n## Kids\' Voices\n\nChildren\'s voices are called **treble** - they can sing higher notes!\n\n## Singing Tips\n\n1. **Stand or sit up straight** - Helps you breathe\n2. **Breathe from your belly** - Deep breaths\n3. **Open your mouth** - Lets sound out\n4. **Practice scales** - Do-Re-Mi-Fa-Sol-La-Ti-Do\n\n## Fun Songs to Practice\n\n- "Happy Birthday" (simple melody)\n- "Twinkle Twinkle Little Star"\n- "Row Row Row Your Boat"\n\n## Activity\n\nPractice matching pitch:\n1. Hum a note\n2. Try to sing the same note\n3. Have someone play a note on an instrument and match it!\n\n## Take Care of Your Voice\n\n- Do not scream or shout\n- Drink water\n- Rest your voice sometimes', difficulty: 'easy', duration: '20 min' },

  // ========== SPECIAL - Joint Lesson (Honor & Noble) ==========
  { id: 'special-tanghulu', title: 'Make Tanghulu! 🍓', subject: 'special', grade: 'honor', description: 'Learn the science of sugar, measure ingredients, and create beautiful candy art — then eat your masterpiece!', content: `# 🍓 Make Tanghulu! 🍓\n\n*A Cross-Curricular Adventure for Honor & Noble*\n\n## What is Tanghulu?\n\nTanghulu (糖葫芦) is a traditional Chinese candy fruit snack made of fruit on bamboo skewers dipped in a thin layer of hardened sugar syrup. People have been eating it for over 700 years!\n\n**Today's Mission:**\n- Learn the SCIENCE of sugar crystallization\n- Practice MATH by measuring ingredients\n- Create ART by making beautiful patterns\n- Work TOGETHER as a team\n\n---\n\n## 🥼 The Science: Why Does Sugar Get Hard?\n\nSugar is made of tiny molecules called **sucrose**. When you dissolve sugar in water and then heat it, the molecules move faster and spread apart. When it cools, they slow down and form a **crystalline structure** — that's the hard, shiny shell!\n\n**Key Science Words:**\n- **Dissolve** — when sugar "disappears\" into hot water\n- **Crystallize** — when sugar molecules arrange into a hard structure\n- **Syrup** — sugar + water that's been heated\n- **Hard Crack Stage** — when sugar is heated to 300°F and forms a hard candy\n\n**Think About It:**\n- Why does the sugar get hard when it touches the cold fruit?\n- What would happen if you used salt instead of sugar?\n\n---\n\n## 🔢 The Math: Measuring Ingredients\n\n**Tanghulu Recipe (Makes 8 skewers)**\n\n| Ingredient | Amount |\n|-----------|--------|\n| Fresh strawberries | 8 |\n| Granulated sugar | 1 cup |\n| Water | 1/2 cup |\n| Bamboo skewers | 8 |\n\n**Math Challenges:**\n\n1. **Doubling the Recipe:**\n   - If we want to make 16 skewers, how much sugar do we need?\n   - How much water?\n\n2. **Fractions:**\n   - 1 cup = 16 tablespoons\n   - 1/2 cup = ? tablespoons\n\n3. **Temperature:**\n   - Water boils at 212°F\n   - Hard crack stage is at 300°F\n   - How many degrees from boiling to hard crack?\n\n4. **Sharing:**\n   - 8 strawberries divided between 2 people = ? each\n   - 1 cup of sugar divided between 2 people = ? each\n\n---\n\n## 🎨 The Art: Making It Beautiful\n\nTanghulu isn't just candy — it's edible art!\n\n**Design Ideas:**\n\n🍓 **Classic Strawberry** — simple and beautiful\n\n🍇 **Grape Clusters** — purple and green together\n\n🌈 **Rainbow Skewer** — strawberry, grape, pineapple, orange\n\n🫐 **Berry Blast** — strawberry, blueberry, raspberry\n\n🍊 **Citrus Swirl** — orange and pineapple chunks\n\n**Design Challenge:**\nBefore you start, DRAW your design on paper!\n- How many fruits will you use?\n- What colors will you combine?\n- Will your skewers be all one color or mixed?\n\n---\n\n## 👩‍🍳 Let's Cook!\n\n### What You Need:\n- 1 cup sugar\n- 1/2 cup water\n- 8 strawberries (or other fruit)\n- 8 bamboo skewers\n- A candy thermometer OR a glass of cold water\n- A medium saucepan\n- A baking sheet lined with parchment paper\n\n### Steps:\n\n**Step 1: Prep the Fruit**\nWash and dry your strawberries completely (water makes the sugar slide off!). Thread them onto bamboo skewers.\n\n**Step 2: Make the Syrup**\n- Pour 1 cup sugar and 1/2 cup water into saucepan\n- Stir just until the sugar is wet (don't stir after!)\n- Heat on medium-high until it boils\n\n**Step 3: Watch the Temperature**\n- Use a candy thermometer OR test in cold water\n- **Thread Test:** Drop a little syrup into cold water\n  - Forms a hard thread = hard crack stage (300°F) ✅\n  - Still soft and bendy = keep cooking\n\n**Step 4: Dip!**\n- Tilt the pan so you have deep syrup\n- Quickly dip each fruit skewer\n- Let excess drip off\n- Place on parchment paper\n\n**Step 5: Wait and Eat**\n- Let cool for 15 minutes until hard\n- The sugar shell will be SHINY and CRUNCHY!\n\n---\n\n## 🤔 Reflection Questions\n\nAfter you eat your tanghulu, answer these:\n\n1. **Science:** What happened to the sugar when we heated it? What happened when it touched the cold fruit?\n\n2. **Math:** How many total strawberries did you and your sibling make? Did you each get the same number?\n\n3. **Art:** What design did you create? Would you change anything next time?\n\n4. **Teamwork:** What was hard about working together? What worked well?\n\n---\n\n## 🎉 Bonus Challenges\n\n**Easy:** Make tanghulu again but with different fruits (grapes, pineapple, mandarin oranges)\n\n**Medium:** Research WHERE tanghulu comes from and write 3 facts about its history\n\n**Hard:** Figure out how to make your sugar shell a different COLOR — hint: try adding a few drops of food coloring to the syrup!\n\n---\n\n**Have fun and enjoy your edible art! 🎨🍬**`, difficulty: 'easy', duration: '60 min' },
  
  // MATH - Noble
  { id: 'noble-math-1', title: 'Multiplication (2-12 Tables)', subject: 'math', grade: 'noble', description: 'Master multiplication tables through 12', content: '# Multiplication Master (2-12)\n\n## Why Memorize?\n\nKnowing your times tables makes math SO much faster!\n\n**The 6 Times Table**\n- 6 x 1 = 6\n- 6 x 2 = 12\n- 6 x 3 = 18\n- 6 x 4 = 24\n- 6 x 5 = 30\n- 6 x 6 = 36\n- 6 x 7 = 42\n- 6 x 8 = 48\n- 6 x 9 = 54\n- 6 x 10 = 60\n- 6 x 11 = 66\n- 6 x 12 = 72\n\n**Tricks:**\n- 6 x 6 = 36 (6+6+6+6+6+6)\n- Double the 3s table! 3x4=12, so 6x4=24\n\n## Mixed Practice\n\n- 7 x 8 = ?\n- 9 x 6 = ?\n- 11 x 5 = ?\n- 12 x 4 = ?\n- 8 x 8 = ?\n\n**Word Problem**\n\nA baker puts 6 cookies in each box. He makes 8 boxes. How many cookies total?\nAnswer: 6 x 8 = **48 cookies**', difficulty: 'medium', duration: '30 min' },
  { id: 'noble-math-2', title: 'Division Basics', subject: 'math', grade: 'noble', description: 'Learn division as sharing equally', content: '# Division Basics\n\n## What is Division?\n\nDivision is sharing equally.\n\n**Example**\n\n12 cookies divided by 4 friends = 3 cookies each\n\nWe split 12 into 4 equal groups.\n\n**The Sign**\nThe divided by sign means "divide"\n\n12 divided by 4 = 3\n\n## Practice Problems\n\n- 20 divided by 5 = ?\n- 36 divided by 6 = ?\n- 48 divided by 8 = ?\n- 25 divided by 5 = ?\n\n**Word Problem**\n\nNoble has 24 marbles. He wants to put them in 6 bags with the same number in each. How many marbles per bag?\nAnswer: 24 divided by 6 = **4 marbles per bag**\n\n## Division and Multiplication Connection\n\n12 divided by 3 = 4 because 3 x 4 = 12\n\n**If you know your multiplication, you know division!**\n\nPractice:\n- If 7 x 5 = 35, then 35 divided by 5 = ?\n- If 9 x 4 = 36, then 36 divided by 9 = ?', difficulty: 'medium', duration: '25 min' },
  { id: 'noble-math-3', title: 'Fractions & Decimals', subject: 'math', grade: 'noble', description: 'Learn to convert fractions to decimals', content: '# Fractions and Decimals\n\n## Fractions Review\n\n1/2 = one half\n1/4 = one quarter\n3/4 = three quarters\n\n## What is a Decimal?\n\nDecimals are another way to show parts of a whole.\n\n**Money Example**\n\n$1.00 = 1 whole dollar\n$.50 = 1/2 dollar (50 cents)\n$.25 = 1/4 dollar (25 cents)\n$.75 = 3/4 dollar (75 cents)\n\n## Common Conversions\n\n| Fraction | Decimal |\n|----------|--------|\n| 1/2 | 0.5 |\n| 1/4 | 0.25 |\n| 3/4 | 0.75 |\n| 1/10 | 0.1 |\n| 1/100 | 0.01 |\n\n## Practice\n\nConvert these fractions to decimals:\n- 2/4 = ?\n- 1/2 + 1/4 = ? (hint: 0.5 + 0.25)\n- 3/10 = ?\n\n**Word Problem**\n\nNoble read 1/2 of his book yesterday and 1/4 today. What fraction did he read total? In decimals?\nAnswer: 1/2 + 1/4 = 2/4 + 1/4 = 3/4 = **0.75 of the book**', difficulty: 'hard', duration: '30 min' },
  { id: 'noble-math-4', title: 'Long Division', subject: 'math', grade: 'noble', description: 'Learn to divide larger numbers', content: '# Long Division\n\n## When to Use Long Division\n\nFor big numbers that do not divide evenly!\n\n**Example:** 156 divided by 4\n\n**Step 1:** 4 into 1 (no) → 4 into 15 (3 times)\nWrite 3 above the 5\n\n**Step 2:** 3 x 4 = 12. Subtract from 15 = 3\n\n**Step 3:** Bring down the 6\n\n**Step 4:** 4 into 36 = 9\n\n**Answer:** 156 ÷ 4 = **39**\n\n## Try These\n\n- 85 ÷ 5 = ?\n- 96 ÷ 3 = ?\n- 144 ÷ 12 = ?\n\n**Word Problem**\n\nA teacher has 156 stickers. She wants to put them equally among 4 students. How many stickers does each student get?\n\nAnswer: 156 ÷ 4 = **39 stickers each**', difficulty: 'hard', duration: '35 min' },
  { id: 'noble-math-5', title: 'Factors and Multiples', subject: 'math', grade: 'noble', description: 'Learn about factors and multiples', content: '# Factors and Multiples\n\n## What is a Factor?\n\nNumbers that divide evenly into another number.\n\n**Factors of 12:**\n1 x 12 = 12\n2 x 6 = 12\n3 x 4 = 12\n\n**Factors of 12: 1, 2, 3, 4, 6, 12**\n\n## Finding Factors\n\n**Is 5 a factor of 20?**\n20 ÷ 5 = 4 (no remainder!) YES!\n\n**Is 6 a factor of 20?**\n20 ÷ 6 = 3 remainder 2. NO!\n\n## What is a Multiple?\n\nA multiple is what you get when you multiply!\n\n**Multiples of 4:**\n4, 8, 12, 16, 20, 24...\n(4 x 1, 4 x 2, 4 x 3...)\n\n**Multiples of 7:**\n7, 14, 21, 28, 35...\n\n## Practice\n\n**Factors of 24:**\n1 x 24 = 24\n2 x 12 = 24\n3 x 8 = 24\n4 x 6 = 24\nFactors: 1, 2, 3, 4, 6, 8, 12, 24\n\n**First 5 multiples of 9:**\n9, 18, 27, 36, 45\n\n## Is it a Factor or Multiple?\n\n- 5 is a ___ of 15 (factor!)\n- 16 is a ___ of 4 (multiple!)\n- 7 is a ___ of 21 (factor!)\n- 30 is a ___ of 10 (multiple!)', difficulty: 'medium', duration: '30 min' },
  { id: 'noble-math-6', title: 'Area and Perimeter', subject: 'math', grade: 'noble', description: 'Calculate area and perimeter of shapes', content: '# Area and Perimeter\n\n## Perimeter = Around the Outside\n\nAdd up ALL the sides!\n\n**Rectangle:**\nLength = 6, Width = 4\nP = 6 + 4 + 6 + 4 = **20 units**\n\n**Shortcut:** P = 2L + 2W = 2(6) + 2(4) = 20\n\n**Square:**\nSide = 5\nP = 5 + 5 + 5 + 5 = **20 units**\n\n## Area = What Fits Inside\n\n**Rectangle:**\nA = Length x Width = 6 x 4 = **24 square units**\n\n**Square:**\nA = Side x Side = 5 x 5 = **25 square units**\n\n## Word Problems\n\n**Problem 1:**\nA rectangular garden is 8 feet long and 5 feet wide. What is the perimeter and area?\n\nPerimeter: 2(8) + 2(5) = 26 feet\nArea: 8 x 5 = 40 square feet\n\n**Problem 2:**\nA square room has sides of 12 feet. How much carpet do you need?\n\nArea: 12 x 12 = **144 square feet**', difficulty: 'medium', duration: '35 min' },
  { id: 'noble-math-7', title: 'Graphs and Data', subject: 'math', grade: 'noble', description: 'Read and create bar graphs and line graphs', content: '# Graphs and Data\n\n## Types of Graphs\n\n**Bar Graph** - Compares things with bars\n**Line Graph** - Shows how something changes over time\n**Pie Chart** - Shows parts of a whole (like a pie!)\n\n## Reading a Bar Graph\n\nA bar graph might show:\n- Favorite ice cream flavors\n- Number of books read each month\n- Test scores in a class\n\n**How to read:**\n1. Look at the title\n2. Check the labels (what does each axis mean?)\n3. Read the numbers/scale\n4. Compare the bars!\n\n## Creating a Bar Graph\n\nSurvey 10 friends: "What is your favorite pet?"\n\n| Pet | Votes |\n|-----|-------|\n| Dog | 4 |\n| Cat | 3 |\n| Fish | 2 |\n| Bird | 1 |\n\nNow draw bars to show this data!\n\n## Line Graphs\n\nUse a line graph when things CHANGE over time:\n- Temperature throughout the week\n- Your height over the year\n- Plants growing over months\n\n**Activity:**\nTrack the high temperature for 7 days and make a line graph!', difficulty: 'medium', duration: '30 min' },

  // READING - Noble
  { id: 'noble-reading-1', title: 'Inference Skills', subject: 'reading', grade: 'noble', description: 'Learn to read between the lines', content: '# Inference Skills\n\n## What is an Inference?\n\nAn inference is a smart guess using:\n- What you READ in the text\n- What you ALREADY know\n\n**Example:**\n\n"She opened her umbrella and stepped outside."\n\nWhat can you infer?\n- It is rainy outside!\n- She wants to stay dry.\n\n## Practice Inference\n\n**Text:**\nMaria grabbed her coat and mittens. She stepped onto the porch and looked up at the gray sky.\n\n**Inference:** It is cold outside! (She bundled up and the sky looks like it might snow or rain.)\n\n## Why Infer?\n\nAuthors do not always tell us everything. We use clues to figure out:\n- How characters feel\n- Why things happen\n- What will happen next\n\n## Try These\n\n1. Jake looked at the clock and ran out the door, grabbing his swim goggles.\n   - What can you infer?\n\n2. Grandma smiled and handed the plate to the clean-plate club member.\n   - What can you infer?\n\n## Think and Discuss\n\nMake inferences about your day today. What clues help you know how people are feeling?', difficulty: 'medium', duration: '25 min' },
  { id: 'noble-reading-2', title: 'Summarizing Texts', subject: 'reading', grade: 'noble', description: 'Learn to summarize what you read', content: '# Summarizing Texts\n\n## What is a Summary?\n\nA summary tells the MAIN points in YOUR OWN words.\n\n**A good summary:**\n- Tells who and what\n- Includes the main idea\n- Leaves out small details\n- Is shorter than the original\n\n## Summarizing Steps\n\n**G** - Generate: Who/what?\n**I** - Is: What happened?\n**S** - So: What was the result?\n**T** - Then: How did it end?\n\n## Example\n\n**Original Paragraph:**\nAmelia was scared of the dark. Every night she needed a nightlight. One night there was a thunderstorm and the power went out. She could not find her flashlight. She tried to stay calm and found her phone flashlight. She felt proud of herself.\n\n**Summary:**\nAmelia was afraid of the dark. When a storm knocked out the power, she could not find her flashlight. She used her phone light instead and felt proud.\n\n## Practice\n\nRead a page from your book and write a 3-sentence summary:\n1. Who is the story about?\n2. What happened?\n3. How did it end?\n\n**Remember:** Do not retell everything - just the important parts!', difficulty: 'medium', duration: '25 min' },
  { id: 'noble-reading-3', title: 'Compare and Contrast', subject: 'reading', grade: 'noble', description: 'Learn to find similarities and differences', content: '# Compare and Contrast\n\n## What Does This Mean?\n\n**Compare** - Find how things are ALIKE\n**Contrast** - Find how things are DIFFERENT\n\n## Signal Words\n\n**Compare (alike):**\n- both\n- similarly\n- also\n- like\n- too\n\n**Contrast (different):**\n- but\n- however\n- unlike\n- different from\n- however\n\n## Example\n\nCompare/Contrast cats and dogs:\n\n**Alike:**\n- Both are pets\n- Both have fur\n- Both need food and water\n\n**Different:**\n- Cats meow, dogs bark\n- Cats land on their feet, dogs do not\n- Cats are usually smaller\n\n## Venn Diagram\n\nUse a Venn diagram to organize:\n- Circle 1: Cats\n- Circle 2: Dogs\n- Overlap: How they are alike\n\n## Practice\n\nCompare two books you have read:\n- What was similar?\n- What was different?\n- Same author or different?\n- Same genre or different?', difficulty: 'medium', duration: '25 min' },
  { id: 'noble-reading-4', title: 'Context Clues', subject: 'reading', grade: 'noble', description: 'Figure out unknown words using clues', content: '# Context Clues\n\n## What are Context Clues?\n\nWhen you see a word you do not know, look at the SENTENCE around it for clues!\n\n## Types of Clues\n\n**1. Definition Clues**\n"The ancient **artifact**, a very old object, was in the museum."\n(They tell you what it means!)\n\n**2. Example Clues**\n"She ate **produce** such as apples, oranges, and bananas."\n(Examples help explain!)\n\n**3. Cause/Effect Clues**\n"Because it was raining, the game was **postponed**."\n(Causation explains the word!)\n\n**4. Contrast Clues**\n"Unlike his **introvert** brother, James loved parties."\n(Contrast shows opposite!)\n\n## Practice\n\nFind the meaning of the bold word:\n\n1. The **diligent** student always finished her homework early. (hardworking / lazy)\n2. The park was **deserted** - not a single person was there. (empty / crowded)\n3. She was **nervous** before the game, but confident during it. (anxious / calm)\n\n## Try It!\n\nRead a paragraph from your book. Find 3 words you do not know and use context clues to figure them out!', difficulty: 'medium', duration: '30 min' },
  { id: 'noble-reading-5', title: 'Figurative Language', subject: 'reading', grade: 'noble', description: 'Learn similes, metaphors, and idioms', content: '# Figurative Language\n\n## What is Figurative Language?\n\nWords that go beyond their literal meaning to create pictures in your mind!\n\n## Similes (uses LIKE or AS)\n\n**"Her eyes sparkled like diamonds."**\nHer eyes are NOT really diamonds, but they SHINE like them!\n\n**"The dog ran as fast as a racecar."**\nThe dog is NOT a car, but it runs VERY fast!\n\n**Common similes:**\n- Busy as a bee\n- Cold as ice\n- Brave as a lion\n- Sleep like a log\n\n## Metaphors (says something IS something else)\n\n**"Life is a rollercoaster."**\nLife is not literally a rollercoaster, but it has ups and downs!\n\n**"Her heart is a fortress."**\nShe is not made of walls, but she is protected and strong!\n\n## Idioms (common phrases)\n\n**"It is raining cats and dogs."**\nIt is NOT really raining animals! It means it is raining very hard!\n\n**Common idioms:**\n- Break a leg (good luck)\n- Let the cat out of the bag (tell a secret)\n- Hit the nail on the head (exactly right)\n- Under the weather (feeling sick)', difficulty: 'medium', duration: '30 min' },

  // SCIENCE - Noble
  { id: 'noble-science-1', title: 'The Water Cycle', subject: 'science', grade: 'noble', description: 'Learn how water moves around Earth', content: '# The Water Cycle\n\n## Earth\'s Water Journey\n\nWater on Earth keeps moving in a big cycle! Here is how:\n\n**Step 1: Evaporation**\nThe sun heats up lakes, rivers, and oceans. Water turns into an invisible gas called vapor and rises into the sky.\n\n**Step 2: Condensation**\nHigh in the sky, it is cold! The vapor cools down and turns into tiny water droplets. These make clouds!\n\n**Step 3: Precipitation**\nWhen clouds get too heavy, water falls back to Earth as rain, snow, sleet, or hail.\n\n**Step 4: Collection**\nWater collects in lakes, rivers, and oceans. Then the sun heats it up and it starts all over again!\n\n## Key Terms\n\n| Word | Meaning |\n|------|---------|\n| Evaporation | Liquid to gas (heating) |\n| Condensation | Gas to liquid (cooling) |\n| Precipitation | Water falling from clouds |\n| Collection | Water gathering in places |\n\n## The Water Cycle Song\n\nEvaporation, condensation, precipitation, collection!\nRound and round, it is a cycle of motion!\n\n## Think About It\n\n- Where does your drinking water come from?\n- Why do you think it rains more in some places?\n- What would happen if there was no evaporation?', difficulty: 'medium', duration: '30 min' },
  { id: 'noble-science-2', title: 'Force & Motion', subject: 'science', grade: 'noble', description: 'Learn about pushes, pulls, and how things move', content: '# Force and Motion\n\n## What is Force?\n\nA force is a push or a pull that makes things move.\n\n**Push Examples:**\n- Pushing a door open\n- Throwing a ball\n- Pushing a shopping cart\n\n**Pull Examples:**\n- Pulling a wagon\n- Opening a drawer\n- Pulling a sled up a hill\n\n## Motion\n\nMotion is how things move:\n\n- **Speed** - How fast or slow\n- **Direction** - Which way (left, right, up, down)\n- **Distance** - How far\n\n## Gravity\n\nGravity is an invisible force that pulls things DOWN toward Earth.\n\n- Why do things fall down?\n- Why do not we float away?\n\n## Friction\n\nFriction is a force that SLOWS things down when they rub together.\n\n**High friction (slows a lot):**\n- Rubber shoes on carpet\n- Hands on a slide\n\n**Low friction (slippery):**\n- Ice skates on ice\n- Bowling ball on waxed floor\n\n## Experiment Ideas\n\n1. How far does a ball roll on carpet vs. tile?\n2. Does a heavier ball roll faster?\n3. Can you make friction work for you (walking, holding a cup)?', difficulty: 'medium', duration: '30 min' },
  { id: 'noble-science-3', title: 'Ecosystems', subject: 'science', grade: 'noble', description: 'Learn about ecosystems and how living things interact', content: '# Ecosystems\n\n## What is an Ecosystem?\n\nAn ecosystem is ALL the living and non-living things in an area working together!\n\n**Living (Biotic):**\n- Plants, animals, bacteria, fungi\n\n**Non-Living (Abiotic):**\n- Water, sunlight, air, soil, temperature\n\n## Food Chains\n\nEnergy flows through ecosystems in food chains:\n\n**Sun → Grass → Rabbit → Fox**\n\n- Grass makes food from sunlight (PRODUCER)\n- Rabbit eats grass (PRIMARY CONSUMER)\n- Fox eats rabbit (SECONDARY CONSUMER)\n\n## Roles in Ecosystems\n\n**Producers** - Plants that make their own food\n**Consumers** - Animals that eat other things\n**Decomposers** - Break down dead things (mushrooms, bacteria)\n\n## Types of Ecosystems\n\n- **Forest** - Many trees, lots of animals\n- **Ocean** - Marine life, coral reefs\n- **Desert** - Hot/cold, dry, few plants\n- **Grassland** - Grasses, few trees\n- **Tundra** - Very cold, permafrost\n- **Wetland** - Wet, marshy (swamps, marshes)\n\n## Think About It\n\nWhat would happen if:\n- All the bees died? (Pollination would stop!)\n- The wolves disappeared from a forest? (Too many deer!)\n- There was no rain for years?', difficulty: 'hard', duration: '35 min' },
  { id: 'noble-science-4', title: 'Electricity and Circuits', subject: 'science', grade: 'noble', description: 'Learn about electrical circuits and energy', content: '# Electricity and Circuits\n\n## What is Electricity?\n\nElectricity is the flow of tiny particles called **electrons** through wires and circuits!\n\n## Parts of a Circuit\n\nFor electricity to flow, you need a COMPLETE path (circuit):\n\n1. **Power source** - Battery, generator\n2. **Wires** - The path electrons travel\n3. **Load** - The thing that uses electricity (bulb, motor)\n4. **Switch** - Turns it on and off\n\n## Open vs Closed Circuit\n\n**Open circuit** - Path is broken, no electricity flows\n**Closed circuit** - Path is complete, electricity flows!\n\n## Types of Circuits\n\n**Series circuit** - One path for electricity\nIf one bulb goes out, ALL go out!\n\n**Parallel circuit** - Multiple paths\nIf one bulb goes out, others stay on!\n\n## Static Electricity\n\nWhen electricity builds up in ONE place:\n- Lightning!\n- Rubbing a balloon on your hair\n- Getting shocked by a doorknob\n\n## Safety\n\n- Never stick things in outlets!\n- Keep electronics away from water!\n- Do not touch power lines!', difficulty: 'medium', duration: '30 min' },
  { id: 'noble-science-5', title: 'Earth\'s Structure', subject: 'science', grade: 'noble', description: 'Learn about Earth\'s layers and tectonic plates', content: '# Earth\'s Structure\n\n## Layers of the Earth\n\n**1. Crust** (outer layer)\n- 5-70 km thick\n- Where we live!\n- Made of rock and soil\n\n**2. Mantle** (middle layer)\n- 2,900 km thick\n- Very hot rock that moves slowly\n- Like really thick syrup\n\n**3. Core** (inner layer)\n- Outer core: Liquid iron, creates magnetic field\n- Inner core: Solid iron, SUPER hot!\n- 5,000-6,000°C!\n\n## Tectonic Plates\n\nEarth\'s crust is broken into BIG pieces called plates:\n\n- They float on the mantle\n- They move very slowly (about as fast as fingernails grow!)\n- When they bump, we get EARTHQUAKES!\n- When they push together, we get MOUNTAINS!\n\n## Fun Facts\n\n- Earth is the only planet with plate tectonics!\n- Mount Everest is still growing (plates pushing together)\n- The San Andreas Fault is where two plates slide past each other\n- About 500,000 earthquakes happen each year!\n\n## Volcanoes\n\nWhen plates separate or move, magma can come up through cracks and erupt as a volcano!\n\n- Magma = molten rock UNDERGROUND\n- Lava = molten rock ABOVE ground', difficulty: 'medium', duration: '35 min' },

  // SOCIAL STUDIES - Noble
  { id: 'noble-ss-1', title: 'US Regions', subject: 'social-studies', grade: 'noble', description: 'Learn about the 5 US regions', content: '# The 5 Regions of the United States\n\n## The 5 Regions\n\n**1. Northeast**\n- States: Maine, Vermont, New Hampshire, Massachusetts, Rhode Island, Connecticut, New York, New Jersey, Pennsylvania\n- Features: Mountains (Appalachians), Fall colors, Big cities (NYC, Boston)\n- Climate: Cold winters, warm summers\n\n**2. Southeast**\n- States: Delaware, Maryland, Virginia, North Carolina, South Carolina, Georgia, Florida, Alabama, Mississippi, Tennessee, Kentucky, West Virginia\n- Features: Beaches, Swamps, Mountains\n- Climate: Hot summers, mild winters\n\n**3. Midwest**\n- States: Ohio, Indiana, Illinois, Michigan, Wisconsin, Minnesota, Iowa, Missouri, North Dakota, South Dakota, Nebraska, Kansas\n- Features: Farms, Great Lakes, Corn fields\n- Climate: Hot summers, cold winters\n\n**4. Southwest**\n- States: Texas, Oklahoma, New Mexico, Arizona, Nevada, Utah (parts)\n- Features: Deserts, Canyons (Grand Canyon!), Mexican culture\n- Climate: Hot and dry\n\n**5. West**\n- States: California, Oregon, Washington, Nevada, Utah, Colorado, Idaho, Montana, Wyoming, Alaska, Hawaii\n- Features: Mountains (Rockies), Oceans, National Parks\n- Climate: Very varied!\n\n## Activity\n\nOn a map, color each region a different color. Label 3 states in each region.\n\n**Bonus:** What region do you live in?', difficulty: 'medium', duration: '35 min' },
  { id: 'noble-ss-2', title: 'American Symbols', subject: 'social-studies', grade: 'noble', description: 'Learn about US patriotic symbols', content: '# American Symbols\n\n## What is a Symbol?\n\nA symbol is something that stands for or represents an idea.\n\n## Important American Symbols\n\n**The Bald Eagle**\n- Our national bird\n- Symbol of freedom\n- Lives near water\n- Has a white head and brown body\n\n**The Statue of Liberty**\n- Located in New York Harbor\n- Gift from France (1886)\n- Holds a torch and a book\n- Welcomes immigrants\n\n**The White House**\n- Where the President lives\n- Located in Washington D.C.\n- Built in 1800\n\n**Mount Rushmore**\n- Carved in South Dakota\n- Shows 4 presidents: Washington, Jefferson, Lincoln, Roosevelt\n- Took 14 years to build\n\n**The American Flag**\n- 50 stars = 50 states\n- 13 stripes = original colonies\n- Red = bravery\n- White = purity\n- Blue = justice\n\n## Other Symbols\n\n- The Liberty Bell\n- The Pledge of Allegiance\n- The National Anthem\n\n## Think About It\n\n- Why do we have symbols?\n- What do these symbols mean to you?\n- What symbolizes YOUR family or community?', difficulty: 'easy', duration: '25 min' },
  { id: 'noble-ss-3', title: 'Branches of Government', subject: 'social-studies', grade: 'noble', description: 'Learn about the 3 branches of US government', content: '# Branches of Government\n\n## Why Three Branches?\n\nThe Founders did not want one person or group to have too much power!\nThis is called **separation of powers**.\n\n## The Three Branches\n\n**1. Legislative (Makes Laws)**\n\nCongress = House of Representatives + Senate\n- House: 435 people, represents states by population\n- Senate: 100 people (2 per state)\n\n**2. Executive (Carries Out Laws)**\n\n- President\n- Vice President\n- Cabinet (helpers like Secretary of Education, etc.)\n\n**3. Judicial (Reviews Laws)**\n\n- Supreme Court (9 judges)\n- Other federal courts\n- Decides if laws follow the Constitution\n\n## Checks and Balances\n\nEach branch can CHECK the others:\n\n- President can VETO laws from Congress\n- Congress can IMPEACH (remove) the President\n- Supreme Court can say a law is UNCONSTITUTIONAL\n\n## Think About It\n\nWhy is it important that no branch has ALL the power?\n\nWhat might happen if one person could make laws, enforce laws, AND judge laws?', difficulty: 'hard', duration: '35 min' },
  { id: 'noble-ss-4', title: 'Autochthonous American Cultures', subject: 'social-studies', grade: 'noble', description: 'Learn about different Autochthonous American nations', content: '# Autochthonous American Cultures\n\n## Before America Was \"Discovered\"\n\nMany different peoples lived on this land for thousands of years. They are the **Autochthonous Americans** — the original peoples of this land.\n\n## Different Nations/Regions\n\n**Northeast (Woodland Peoples)**\n- Iroquois, Cherokee, Algonquian\n- Lived in longhouses and wigwams\n- Hunted, fished, grew corn, beans, squash\n\n**Plains (Prairie Peoples)**\n- Lakota, Cheyenne, Comanche\n- Moved to follow buffalo\n- Lived in teepees\n- Buffalo were very important\n\n**Southwest**\n- Pueblo, Hopi, Navajo\n- Built adobe homes (mud bricks)\n- Hot, dry climate\n- Irrigation for farming\n\n**Pacific Northwest**\n- Chinook, Nez Perce, Haida\n- Fished for salmon\n- Carved totem poles\n- Cedar bark houses\n\n## What We Learn From\n\nAutochthonous Americans taught settlers:\n- How to grow corn, beans, and squash (Three Sisters)\n- How to use natural medicines\n- How to survive in different environments\n\n## Today\n\nThere are more than 570 federally recognized Autochthonous American nations in the US today, each with its own government, culture, and traditions.', difficulty: 'medium', duration: '30 min' },

  // ART - Noble
  { id: 'noble-art-1', title: 'Color Theory', subject: 'art', grade: 'noble', description: 'Learn primary, secondary, and tertiary colors', content: '# Color Theory\n\n## Primary Colors\n\nThese 3 colors can make ALL other colors:\n- Red\n- Blue\n- Yellow\n\n## Secondary Colors\n\nMix two primaries to get:\n- Red + Blue = Purple\n- Red + Yellow = Orange\n- Blue + Yellow = Green\n\n## Tertiary Colors\n\nMix a primary with a nearby secondary:\n- Red + Orange = Red-Orange\n- Blue + Green = Blue-Green\n- Yellow + Orange = Yellow-Orange\n\n## Color Moods\n\n**Warm Colors** (red, orange, yellow)\n- Feel energetic, happy, excited\n- Remind us of sun, fire, warmth\n\n**Cool Colors** (blue, green, purple)\n- Feel calm, peaceful, cool\n- Remind us of water, forest, sky\n\n## Activity\n\n**Challenge:** Create a color wheel showing all primary, secondary, and tertiary colors.\n\n**Art Project:**\nDraw a landscape using ONLY warm colors.\nThen draw the same landscape using ONLY cool colors.\nHow do they make you feel different?', difficulty: 'medium', duration: '35 min' },
  { id: 'noble-art-2', title: 'Perspective Drawing', subject: 'art', grade: 'noble', description: 'Learn one-point and two-point perspective', content: '# Perspective Drawing\n\n## What is Perspective?\n\nPerspective makes drawings look 3D on a flat paper!\n\nIt shows how things look smaller when they are FAR AWAY.\n\n## One-Point Perspective\n\nAll lines go to ONE point on the horizon.\n\nUse for: Looking straight down a road, hallway, or tracks\n\n**How to:**\n1. Draw a horizon line\n2. Put a dot (vanishing point) on it\n3. Draw lines from the dot to corners of your paper\n4. Add shapes using those lines!\n\n## Two-Point Perspective\n\nLines go to TWO points on the horizon!\n\nUse for: Drawing buildings from the corner\n\n## Depth Cues\n\nMake things look closer or farther:\n\n**Closer:**\n- Larger\n- More detailed\n- Brighter colors\n- Lower on the paper\n\n**Farther:**\n- Smaller\n- Less detail\n- Duller colors\n- Higher on the paper\n\n## Practice\n\nDraw a road disappearing into the distance using one-point perspective!\n\nDraw a building from the corner using two-point perspective!', difficulty: 'hard', duration: '40 min' },
  { id: 'noble-art-3', title: 'Art Through History', subject: 'art', grade: 'noble', description: 'Learn about different art movements', content: '# Art Through History\n\n## Art Changes Over Time\n\nDifferent eras had different styles!\n\n## Ancient Art (Very Old!)\n- Cave paintings, pyramids, sculpture\n- Shows gods, kings, everyday life\n\n## Renaissance (1400s-1600s)\n\n**Michelangelo, Leonardo da Vinci, Raphael**\n- Realistic human figures\n- Perspective and depth\n- Religious themes\n- Beautiful, balanced\n\n## Impressionism (1800s)\n\n**Monet, Renoir, Degas**\n- Visible brushstrokes\n- Capturing light and movement\n- Everyday scenes\n- outdoors (plein air)\n\n## Modern Art (1900s+)\n\n**Picasso, Kandinsky, Warhol**\n- Breaks the rules!\n- Abstract (not realistic)\n- Bold colors and shapes\n- New materials and ideas\n\n## Contemporary (Today!)\n\n**Various artists**\n- Digital art\n- Installations\n- Mixed media\n- Anything goes!\n\n## Create Your Own Era\n\nTry drawing the same scene in different styles:\n1. Ancient (simple shapes, flat)\n2. Renaissance (realistic, shaded)\n3. Impressionist (loose brushstrokes)\n4. Modern (abstract, bold)', difficulty: 'medium', duration: '35 min' },

  // MUSIC - Noble
  { id: 'noble-music-1', title: 'Reading Music Notes', subject: 'music', grade: 'noble', description: 'Learn the musical alphabet and note names', content: '# Reading Music Notes\n\n## The Musical Alphabet\n\nThere are only 7 letters in music:\n\nA - B - C - D - E - F - G\n\nThen it starts over: A - B - C - D - E - F - G - A...\n\n## The Treble Clef (G Clef)\n\nThe treble clef is used for high pitches.\n\n**Notes on the Lines:**\nE - G - B - D - F (Every Good Boy Does Fine)\n\n**Notes in the Spaces:**\nF - A - C - E\n(spell the word: FACE)\n\n## The Bass Clef (F Clef)\n\nThe bass clef is used for low pitches.\n\n**Notes on the Lines:**\nG - B - D - F - A (Good Boys Do Fine Always)\n\n**Notes in the Spaces:**\nA - C - E - G (All Cows Eat Grass)\n\n## Practice\n\n1. Write the musical alphabet from A to G five times\n2. Draw a treble clef staff and fill in the space notes: F A C E\n3. Find middle C on a piano (it is in between the treble and bass clef!)\n\n## Fun Fact\n\nPiano has 88 keys!\n- 52 white keys\n- 36 black keys\n- 7 notes repeating over and over', difficulty: 'medium', duration: '30 min' },
  { id: 'noble-music-2', title: 'Music Composition Basics', subject: 'music', grade: 'noble', description: 'Learn to write your own music', content: '# Music Composition Basics\n\n## What is Composition?\n\nComposition is writing YOUR OWN music!\n\nEvery song has these elements:\n\n**1. Melody** - The main tune (the part you hum)\n**2. Rhythm** - The beat and timing\n**3. Harmony** - Notes that go with the melody (chords)\n**4. Dynamics** - Loud and soft\n**5. Tempo** - Fast and slow\n\n## Creating a Melody\n\nStart with a scale (like Do-Re-Mi):\n\nPick 4-8 notes that sound good together\n\nRepeat some notes\n\nGo up sometimes, down sometimes\n\n## Rhythm Patterns\n\nCreate a pattern using:\n- Long notes (half notes, whole notes)\n- Short notes (quarter notes, eighth notes)\n- Rests (silence)\n\n## Song Structure\n\n**A-B-A Form:**\n- A section = main melody (repeats)\n- B section = new melody (contrast)\n- A section = back to main\n\n**Example:** Twinkle Twinkle\n- A = \"Twinkle twinkle little star\"\n- B = \"How I wonder what you are\"\n- A = \"Hide above the world so high\"\n\n## Write Your Own!\n\n1. Choose a scale (C major is easy)\n2. Pick 4 notes for your main melody\n3. Add a different 4 notes for contrast\n4. Choose your tempo and dynamics\n5. Try it on an instrument!', difficulty: 'hard', duration: '40 min' },
  { id: 'noble-music-3', title: 'Music Around the World', subject: 'music', grade: 'noble', description: 'Learn about music from different cultures', content: '# Music Around the World\n\n## Music is Everywhere!\n\nEvery culture in the world has music, but it sounds different everywhere!\n\n## African Music\n\n**West Africa (Nigeria, Ghana)**\n- Complex rhythms using multiple drums\n- Call and response singing\n- Griots (storyteller musicians)\n\n**South Africa**\n- A cappella (no instruments) singing\n- Gospel and choral music\n- \"Ladysmith Black Mambazo\"\n\n## Latin American Music\n\n**Brazil**\n- Samba, bossa nova\n- Rhythm from percussion (tamborine, surdo)\n- Dance music!\n\n**Mexico**\n- Mariachi (trumpets, violins)\n- Ranchera, corridos\n\n## Asian Music\n\n**India**\n- Ragas (melodic patterns)\n- Sitar, tabla (drums)\n- Ornamental, sliding notes\n\n**Japan**\n- Traditional: Koto, shakuhachi flute\n- Taiko drums\n- Cherry blossom festivals\n\n## European Music\n\n**Ireland**\n- Fiddle, tin whistle, bagpipes\n- Jigs and reels (dancing music)\n\n**Spain**\n- Flamenco (guitar, singing, dancing)\n- Passionate and rhythmic\n\n## Activity\n\nListen to music from a different country. What do you notice that is:\n- Similar to music you know?\n- Different from music you know?', difficulty: 'medium', duration: '30 min' },
];

